from course import predict, mse_loss, gd_step

def fit_minibatch(X, y, w0, b0, lr, epochs, batch_size):
    w, b = list(w0), b0
    losses = [mse_loss(predict(X, w, b), y)]
    for _ in range(epochs):
        for start in range(0, len(X), batch_size):
            w, b = gd_step(X[start:start + batch_size], y[start:start + batch_size], w, b, lr)
        losses.append(mse_loss(predict(X, w, b), y))
    return [w, b, losses]

def quadratic_descent(w0, target, lr, steps):
    w = w0
    for _ in range(steps):
        grad = 2 * (w - target)
        w -= lr * grad
    return w

def momentum_step(w, v, grad, lr, beta):
    v_next = beta * v + lr * grad
    return [w - v_next, v_next]

def min_max_scale(values):
    lo, hi = min(values), max(values)
    if hi == lo:
        return [0.0] * len(values)
    return [(x - lo) / (hi - lo) for x in values]

import math

def standardize(values):
    mean = sum(values) / len(values)
    std = math.sqrt(sum((x - mean) ** 2 for x in values) / len(values))
    if std == 0:
        return [0.0] * len(values)
    return [(x - mean) / std for x in values]

import math

def sigmoid(x):
    if x >= 0:
        return 1 / (1 + math.exp(-x))
    e = math.exp(x)
    return e / (1 + e)

import math

def binary_cross_entropy(pred, target, eps=1e-7):
    loss = 0.0
    for p, y in zip(pred, target):
        p = min(max(p, eps), 1 - eps)
        loss -= y * math.log(p) + (1 - y) * math.log(1 - p)
    return loss / len(pred)

import math

def categorical_cross_entropy(probs, labels, eps=1e-7):
    return -sum(math.log(max(row[label], eps)) for row, label in zip(probs, labels)) / len(labels)

import math

def token_ratios(new_logp, old_logp):
    return [math.exp(new - old) for new, old in zip(new_logp, old_logp)]

import math

def sequence_ratio(new_logp, old_logp, mask):
    length = sum(mask)
    if length == 0:
        raise ValueError('유효 토큰이 없습니다.')
    log_ratio = sum((n - o) * m for n, o, m in zip(new_logp, old_logp, mask))
    return math.exp(log_ratio / length)

